insert into public.scholarships (slug,name,country_slug,provider,degree_levels,funding_type,funding_details,deadline,deadline_note,eligibility_summary,official_url,last_verified,is_published) values
('world-in-serbia', 'World in Serbia', 'serbia', 'Government of the Republic of Serbia (Ministry of Education; Ministry of Foreign Affairs)', array['bachelor', 'master', 'doctoral']::text[], 'full', 'The official page lists: free tuition, dormitory housing and meals, a monthly allowance, health insurance and an intensive Serbian-language course before enrolment.', null, 'The Ministry of Education announces a competition each year; no dates were stated on the page. Check the official page for the current call.', 'Per the official page: candidates from African, Asian, and Central and South American countries that are members or observer states of the Non-Aligned Movement, studying at state-founded universities. Confirm on the official page whether your country qualifies.', 'https://welcometoserbia.gov.rs/scholarships', '2026-10-22', true),
('mexican-government-scholarships-international-students', 'Mexican Government Scholarships for International Students (Becas de Excelencia)', 'mexico', 'AMEXCID, on behalf of Mexico''s Ministry of Foreign Affairs (SRE)', array['specialization', 'master', 'doctoral', 'research', 'academic mobility']::text[], 'not_stated', 'The official page we read does not state what the scholarships cover. Check the current call.', null, 'The page we read was last updated on 27 August 2020 and refers to a 2020 call. Confirm the current call and dates on the official site.', 'Per the official page: foreign citizens from more than 180 countries under bilateral, multilateral or special agreements, studying at participating Mexican institutions in programmes registered with CONACYT as National Quality Graduate Programmes.', 'https://consulmex.sre.gob.mx/hongkong/index.php/for-foreigners/studyinmexico/becas', '2026-10-22', true)
